arguments.command:
python - <<'PY'
import csv, math
from collections import defaultdict

p='data/workload.csv'
totals=defaultdict(float); errors=[]; first={}; duplicates=[]; valid=0
with open(p, newline='', encoding='utf-8-sig') as f:
    r=csv.DictReader(f)
    for line,row in enumerate(r,2):
        tid=(row.get('task_id') or '').strip(); owner=(row.get('owner') or '').strip(); raw=(row.get('hours') or '').strip()
        try:
            if not tid or not owner or not raw: raise ValueError('thiếu task_id/owner/hours')
            h=float(raw)
            if not math.isfinite(h): raise ValueError('hours không hữu hạn')
        except (ValueError,TypeError) as e:
            errors.append((line,str(e))); continue
        if tid in first: duplicates.append((line,tid,first[tid]))
        else: first[tid]=line
        totals[owner]+=h; valid+=1
print('Tổng hours theo owner:')
for owner in sorted(totals): print(f'{owner}: {totals[owner]:g}')
print(f'Dòng hợp lệ: {valid}')
print(f'Dòng lỗi: {len(errors)}')
for x in errors: print(f'  dòng {x[0]}: {x[1]}')
print(f'task_id trùng: {len(duplicates)}')
for line,tid,firstline in duplicates: print(f'  {tid!r}: dòng {line}, trùng dòng {firstline}')
